INSERT INTO `review` VALUES (1,2,5,'I had never been to Dalhousie before and honestly had no idea what to expect — GoHigh made the entire experience effortless. The Hyundai Creta was spotless, fuel-efficient and handled the winding hill roads beautifully. Khajjiar meadow left me completely speechless — it genuinely looks like Switzerland! The GoHigh team sent a detailed route guide before the trip which was incredibly helpful. Checkout was smooth, no hidden charges, everything was exactly as described. This is now my go-to platform for Himalayan road trips.\"','2026-03-14 13:41:06','travelling',NULL);
